  "msg.voucherSubject": "Your gift voucher for {venue}",
  "msg.voucher": "Hi {name}! Your {amount} gift voucher for {venue} is ready.\n\nCode: {code}\nValid until {until}.\n\nPrint it or send it on: {link}\n\nWhoever has it signs in at {site} and enters the code on their account page, and it becomes credit at {venue}.",
  "msg.reviewSubject": "How was {venue}?",
  "msg.review": "Hi {name}! How was {court} at {venue} on {date}?\n\nRate your visit in a few seconds: {link}\n\nYour review helps other players choose, and the venue to improve. This is the only time {site} will ask about {venue}.",
  "msg.mktConfirmSubject": "{venue}: confirm you want news and offers",
  "msg.mktConfirm": "Somebody booking at {venue} asked for news and offers to be sent to this address. Nothing is sent until you say yes: {link}\n\nIf it was not you, ignore this email and nothing more will come.\n\n{site}",
  "msg.loyaltySubject": "{venue}: an hour on us",
  "msg.loyalty": "Hi {name}, thank you for playing at {venue} so often. Every {every} hours you play here earns you one hour free, and you have earned one.\n\nIt is pass {code}: book at {link} and choose to pay with a pass, or show it at the counter. Good until {until}.\n\n{site}",
  "msg.accountInvoiceSubject": "{venue}: invoice {number} for {account}",
  "msg.accountInvoice": "Hello,\n\nHere is invoice {number} from {venue} for {account}: the bookings charged to your account, {total} in all, due by {due}.\n\nSee it, print it or save it as a PDF: {link}\n\n{site}",
  "msg.hireEnquirySubject": "{venue}: a private hire enquiry from {name}",
  "msg.hireEnquiry": "{name} asked about private hire at {venue}.\n\nWhat for: {kind}\nDate: {date}\nPeople: {people}\nPhone: {phone}\nEmail: {email}\n\n{message}\n\nAnswer them, then mark it on the dashboard under Bookings.",
