  // PRIV1: minors' names on public pages, and a guardian's authorisation of the full name
  "pn1.title": "Names on public pages",
  "pn1.intro": "Draws, results, tables, ladders and live pages show a child by first name and the initial of the next name, for example “Aina L.”, unless you allow the full name below. It is your choice alone: the venue cannot make it for you, and entering an event does not mean yes.",
  "pn1.rules": "You can allow it for one event, or for all of this child's entries at one venue for {months} months. You can withdraw it at any time, and the next page load shows the short name again. It also ends by itself when the event or season ends, after {months} months for a venue, or if you stop managing the child. It is kept in {name}'s history and in the venue's activity log.",
  "pn1.open": "Names on public pages",
  "pn1.none": "{name} has no place in an event, league or ladder just now, so there is nothing to allow.",
  "pn1.pick": "Allow the full name for",
  "pn1.choice.tournament": "{name}, a tournament at {venue} (until {date})",
  "pn1.choice.league": "{name}, a league at {venue} (this season)",
  "pn1.choice.ladder": "{name}, a ladder at {venue} (this season)",
  "pn1.choice.venue": "All {child}'s entries at {venue}, for {months} months",
  "pn1.confirm": "I am {child}'s parent or guardian. I understand that their full name will be public on those pages until I withdraw it or it ends.",
  "pn1.allow": "Allow the full name",
  "pn1.inForce": "Allowed now",
  "pn1.inForce.event": "{event} at {venue}: until the event or season ends, or you withdraw it",
  "pn1.inForce.venue": "All entries at {venue}: until {date}, or you withdraw it",
  "pn1.byOther": "given by another guardian",
  "pn1.withdraw": "Withdraw",
  "pn1.done": "Allowed. Their full name is public there until it ends or you withdraw it.",
  "pn1.withdrawn": "Withdrawn. The short name shows again from the next page load.",
  "pn1.wording.event": "I am the parent or guardian of {child}. I allow {child}'s full name to be shown on the public pages of {event} at {venue} (draws, results, tables and the live page) until that event or season ends, or until I withdraw this. I can withdraw it at any time.",
  "pn1.wording.venue": "I am the parent or guardian of {child}. I allow {child}'s full name to be shown on the public pages of all {child}'s competitive entries at {venue} (draws, results, tables, ladders and the live page) for {months} months, or until I withdraw this. I can withdraw it at any time.",
  "pn1.privacyLead": "A child's name on public pages.",
  "pn1.privacyBody": "A child entered in a tournament, league or ladder is shown on public pages, the live page and in notices to other families by first name and the initial of the next name. Their parent or guardian may allow the full name for one event, or for all their entries at one venue for {months} months, and can withdraw it at any time. It is recorded as the guardian declared it and never verified. {site} has not yet had the wording of this authorisation reviewed by a lawyer.",
  "err.PN1_NOT_GUARDIAN": "You do not manage them.",
  "err.PN1_NO_ENTRY": "They hold no place there.",
  "err.PN1_NO_SEASON": "No season is planned or running yet: allow it once there is one.",
  "err.PN1_OVER": "That event is over.",
  "err.PN1_SCOPE": "Choose one event, or every entry at one venue.",
  "err.PN1_CONFIRM": "Tick the box to say that you understand what becomes public.",
  "err.PN1_NOT_FOUND": "That authorisation was not found.",
  "fi1.consolationNote": "Players who lose in the main draw, except in the final, play on here.",
  "err.RT_RANK_AFTER": "Choose a whole number of counted results from {min} to {max}.",
  "err.RT_PROVISIONAL_NEEDS_PUBLIC": "Public rankings have to be on before players who are not ranked yet can be shown.",
  "rk1.note": "A rating is an estimate worked out from the results counted. With few results it can move a lot, and {n} results do not make it exact.",
  "rk1.venueSets": "Each venue chooses how many counted results a player needs to be ranked there (the usual number is {n}).",
  "rk1.provisional.title": "Provisional: fewer than {n} rated results; these ratings may move a lot",
  "rk1.provisional.intro":
    "These players and teams are not ranked. They have fewer than {n} rated results here, so their ratings are rough estimates. They are listed by name, not in order, and only because they chose to be listed.",
  "rk1.provisional.caption": "Provisional ratings (not ranked)",
