  "pmsg.title": "Messages",
  "pmsg.link": "Messages",
  "pmsg.intro": "Short text messages between people who already share a game, a team, a group or a match.",
  "pmsg.first.title": "Let people I play with message me",
  "pmsg.first.what": "You can write to the people in a game, team, group or match you are in, and they can write to you. Nobody can look you up, search for you or message you out of the blue: a conversation exists only inside something you already share, and it ends with it.",
  "pmsg.first.private": "Your phone number and email address are never shown, and a message cannot contain a phone number or an email address. Messages are text only: no pictures or files.",
  "pmsg.first.safe": "You can mute a conversation, block someone and report a message at any time. Blocking says nothing to them. A report sends a copy of the last messages to the venue's staff (or the site's owners where there is no venue); nobody else reads your messages.",
  "pmsg.first.adults": "Messages are for players who say they are 18 or over. A child never messages anyone privately: a child can write only in the shared conversation of a supervised youth group, with a guardian's consent and a supervisor who can read it. Where a child is in a team or a match, the message goes to and from their guardian, shown with the child's short name only.",
  "pmsg.first.email": "We can email you that you have a message in a place. The email never contains the message itself, and you get at most one a few hours for each conversation.",
  "pmsg.first.understood": "I have read this",
  "pmsg.first.turnOn": "Turn on messages",
  "pmsg.first.needAdult": "You have not said you are 18 or over, so messages are not available to you. You can say so in your playing preferences.",
