  "pmy.first.title": "Messages in your group",
  "pmy.first.what": "Your group has supervisors. You can write in the group's shared conversation, and never to one person privately.",
  "pmy.first.who": "Who can read it: the group's supervisors, the adults they let in, the other people in the conversation, and your guardian. A supervisor can read every message, and can remove a message, pause someone or close the conversation. If the group asked a venue to look after it, that venue's managers can read it too, and each time is recorded.",
  "pmy.first.rules": "Messages are text only and short. Phone numbers, emails, links and social media names cannot be sent. Messages rest at night.",
  "pmy.first.safe": "You can report any message with the Report button. Your guardian is told if you report something, and any guardian can switch messaging off for you at any time. Once it is off, it stays off until your guardians who decide agree, or the venue settles it.",
