  "safe1.form.hard": "This window is marked hard by the venue: nothing overrides it.",
  "err.LAD4_CAP_ACTIVE": "You or your opponent already have {n} courts held at once, which is the most. A court is held only while a match waits to be played: when one is played, let go or lapses, you can have another. Meanwhile book a court the ordinary way and add its code, or ask the venue.",
  "err.LAD4_COURT_CHANGED": "The court shown, {court}, is no longer free on {date} at {time}, so nothing was held and nothing has changed. Look at the time again to see which court would be held.",
  "lad4.mail.agreed": "You both agreed this exact time ({minutes} minutes of play), so the court is confirmed: nobody needs to confirm it again.",
  "lad4.mail.changed.s": "The match time or court was changed: {l}",
  "lad4.mail.changed.b": "The venue changed your match in {l} to {court}, {date} at {time}. It was {oldCourt}, {oldDate} at {oldTime}. The reason given: {why}. You had not both agreed this change, so it is not confirmed yet. Nothing is charged.",
  "lad4.mail.changedConfirm": "Please confirm the new court by {by}, or it is let go: open the ladder and confirm. Both players need to confirm.",
  "lad4.ui.check": "Check the court and accept",
  "lad4.ui.checkAgree": "Check the court and agree",
  "lad4.ui.checkAsk": "Check the court and ask {name}",
  "lad4.ui.checking": "Checking the court…",
  "lad4.ui.title": "Check before you agree",
  "lad4.ui.court": "Court: {court}",
  "lad4.ui.courtNote": "This is the court that would be held for you now. It is reserved only if the hold succeeds: if it is taken first, nothing is reserved, you are told why and nothing changes.",
  "lad4.ui.when": "{date}, {time} to {end}: {minutes} minutes of play (the court's set-up time is held either side).",
  "lad4.ui.charges": "Charges: holding the court is free and moves no money in {site}. If you play on this court the venue's own court hire terms apply; no price is set or charged here. To pay for the court, book it through the venue's booking page and add that booking to this challenge.",
  "lad4.ui.effect.confirmed": "{name} proposed this exact time and you are agreeing it as it is, so the court is confirmed as soon as it is held: nobody has to confirm again.",
  "lad4.ui.effect.tentative": "This is not a time {name} has proposed as it is, so the court is held but tentative: both of you must confirm it, or it is let go.",
  "lad4.ui.effect.askConfirmed": "If {name} agrees this exact time, the court is held and confirmed at once: nobody has to confirm again. Nothing is held until they agree.",
  "lad4.ui.implications": "What this means",
