  "err.LAD5_STALE": "That proposal has been replaced by a newer one, shown now. Nothing was agreed or held: look at the current proposal and answer that one.",
  "err.LAD5_REV_NEEDED": "Say which proposal you are answering (its revision): reload the challenge and try again.",
  "err.LAD5_EXPIRED": "That proposal was not answered by {date}, so it can no longer be accepted. Nothing was agreed or held; propose a time again if you still want to play.",
  "err.LAD5_TERMS": "The match length for this ladder changed after that time was proposed, so what was agreed is no longer what would be held. The proposal has ended; nothing was agreed or held. Please propose a time again.",
  "err.LAD5_PAUSED": "New court holds are paused for you for {hours} hours after the last of {n} held courts you cancelled in the last {days} days, until {until}. This is not a penalty: you can still propose, accept and play, and you can book a court the ordinary way and add its code, or ask the venue.",
  "lad5.mail.counter": "{name} has proposed this exact time and agreed to it. A proposal reserves nothing: a court ({minutes} minutes of play) is held only if you accept this exact time and a court is free, under the venue's usual rules. If you would rather play at another time, propose it.",
  "lad5.mail.noHold": "No court is held for this match: book a court the ordinary way and add its code to the challenge, or ask the venue.",
  "lad5.mail.moveLapsed.s": "A request to change the match time was not answered: {l}",
  "lad5.mail.moveLapsed.b": "The request to change your match in {l} to {date} at {time} was not answered in time, so it has ended. Nothing has changed and nobody is at fault: the match stays as it was, and either of you can ask for a time again.",
  "lad5.ui.checkCounter": "Check the court and propose this time",
  "lad5.ui.goCounter": "Send my proposal",
  "lad5.ui.effect.proposal": "This is your proposal; it is not a reservation. Sending it is your agreement to this exact time. {name} must accept it as it is before any court is held, and then only if a court is free. If {name} proposes something else, nothing here is agreed.",
  "lad5.ui.noGuarantee": "Agreeing a time does not by itself reserve a court. A court is reserved only if it is successfully held, under the venue's usual rules: opening hours, other bookings, limits and who may play.",
  "lad5.ui.paused": "New court holds are paused for you until {until}. You can still accept: the match is agreed and no court is held. Book a court the ordinary way and add its code, or ask the venue.",
  "lad5.ui.goNoHold": "Accept without a held court",
