  "pmy.mail.consentRestored": "The guardians who decide have all agreed: messaging for {child} in the supervised youth group {group} can now be on. You can switch it off at any time from your account page.",
  "pmy.mail.settled": "The venue has settled the hold on messaging for {child} in the supervised youth group {group}. Messaging stays off until a guardian who decides switches it on again from the account page.",
  "pmy.guardian.disagree": "If one guardian switches messaging off, it stays off until all guardians who decide agree again, or the venue settles it. Another guardian switching it on cannot undo that on their own.",
  "pmy.guardian.needsAgreement": "Messaging for {child} here is off and needs agreement from all guardians who decide.",
