  "err.GUEST_INVITATION_INVALID": "Jemputan ini tidak boleh digunakan. Ia mungkin telah tamat tempoh, telah digunakan atau diganti, atau dihantar ke alamat e-mel selain akaun ini. Minta orang yang menjemput anda menghantarnya semula.",
  "gi6.email": "E-mel mereka (pilihan)",
  "gi6.emailHintChecks": "Berikan e-mel mereka dan mereka akan dihantar jemputan untuk diterima dengan akaun mereka, atau akaun baharu; selepas itu mereka boleh menempah dalam talian. Tanpanya, mereka boleh menempah selepas mengesahkan nombor ini pada akaun mereka.",
  "gi6.emailHintNoChecks": "Berikan e-mel mereka supaya mereka dihantar jemputan untuk diterima dengan akaun mereka, atau akaun baharu; selepas itu mereka boleh menempah dalam talian. Tanpanya, pihak pengurusan perlu memautkan akaun mereka dahulu.",
  "gi6.sent": "{name} kini dalam senarai. Jemputan telah dihantar: jika penerima boleh menerima jemputan, mereka akan menerima arahan selanjutnya. Tempahan mereka dikira dalam had unit anda.",
  "gi6.invitationSent": "jemputan dihantar, belum diterima",
  "gi6.mail.subject": "{by} menjemput anda ke {venue}",
  "gi6.mail.body": "{by} telah memasukkan anda ke dalam senarai tetamu {venue}, sehingga {until}.\n\nUntuk menempah di sana dalam talian, terima jemputan ini: buka pautan ini dan log masuk dengan akaun yang menggunakan alamat e-mel ini, atau buat akaun dengannya.\n\n{link}\n\nPautan ini boleh digunakan sekali sahaja, sehingga {until}. Jika anda tidak menjangkakannya, abaikan e-mel ini: tiada apa-apa berlaku melainkan ia diterima.",
  "gi6.title": "Jemputan tetamu",
