  // Players invited to a game or a group by email: an invitation to accept, never a lookup of the address (gi7.)
  "err.PLAYER_INVITATION_INVALID": "Jemputan ini tidak boleh digunakan. Ia mungkin telah tamat tempoh, telah digunakan atau diganti, atau dihantar ke alamat e-mel selain akaun ini. Minta orang yang menjemput anda menghantarnya semula.",
