  "gi7.mail.game.s": "{by} menjemput anda ke permainan: {venue}, {when}",
  "gi7.mail.game.b": "{by} telah menjemput anda ke permainan {host}: {court}, {venue}, {when}.\n\nUntuk bersetuju, buka pautan ini dan log masuk dengan akaun yang menggunakan alamat e-mel ini, atau buat akaun dengannya.\n\n{link}\n\nPautan ini boleh digunakan sekali sahaja, selama {hours} jam paling lama dan tidak selepas permainan bermula. Tiada apa-apa ditempah atau dibayar sehingga anda bersetuju. Jika anda tidak menjangkakannya, abaikan e-mel ini: tiada apa-apa berlaku melainkan ia diterima.",
  "gi7.mail.group.s": "{by} menjemput anda ke {g}",
  "gi7.mail.group.b": "{by} telah menjemput anda untuk menyertai {g}, sekumpulan pemain yang bermain bersama.\n\nUntuk bersetuju, buka pautan ini dan log masuk dengan akaun yang menggunakan alamat e-mel ini, atau buat akaun dengannya.\n\n{link}\n\nPautan ini boleh digunakan sekali sahaja, selama {days} hari. Ahli boleh menjemput satu sama lain ke permainan; tiada apa-apa ditempah atau dibayar dengan menyertai. Jika anda tidak menjangkakannya, abaikan e-mel ini: tiada apa-apa berlaku melainkan ia diterima.",
  "gi7.title": "Jemputan bermain",
  "gi7.intro": "Menerima jemputan ini bermakna anda menyahut jemputan ke permainan atau kumpulan yang dihantar kepada anda. Log masuk dengan akaun yang menggunakan alamat e-mel yang menerima jemputan ini.",
  "gi7.signedOut": "Log masuk dengan akaun yang menggunakan alamat e-mel yang menerima jemputan ini, atau buat akaun dengan alamat itu. Anda akan kembali ke sini untuk menerimanya.",
