  "err.R9_DESK_SERIES": "Tempahan mingguan memerlukan akaun pelanggan sendiri. Minta mereka menempah selepas log masuk, atau minta pengurus menempahnya untuk mereka sebagai tempahan dibantu jika pusat membenarkannya.",
  "err.R9_DESK_LIMIT_UPCOMING": "Peraturan pusat membenarkan {n} tempahan akan datang pada satu masa bagi setiap orang atau isi rumah, dan nombor ini sudah mencapainya. Pengurus boleh mengatasinya untuk satu tempahan jika pusat membenarkannya.",
  "err.R9_DESK_LIMIT_WEEK": "Peraturan pusat membenarkan {n} tempahan seminggu bagi setiap orang atau isi rumah, dan minggu itu sudah penuh untuk nombor ini. Pengurus boleh mengatasinya untuk satu tempahan jika pusat membenarkannya.",
  "err.R9_DESK_LIMIT_DAY": "Peraturan pusat membenarkan {n} tempahan sehari bagi setiap orang atau isi rumah, dan hari itu sudah penuh untuk nombor ini. Pengurus boleh mengatasinya untuk satu tempahan jika pusat membenarkannya.",
  "err.R9_DESK_NOT_MEMBER": "Pusat ini untuk ahli sahaja: nombor ini tiada keahlian di sini dan tiada dalam senarai pusat, dan bukan semua yang dinamakan mempunyai keahlian sendiri. Jual keahlian atau tambah mereka ke senarai dahulu: ini tidak boleh diatasi.",
