  "fit.s.pass-sell.x.online": "Pengurus juga boleh menawarkan pas dalam talian: pelanggan membelinya di halaman pusat dan membayar melalui akaun pembayaran pusat, dan pas dikeluarkan sebaik sahaja dibayar.",
