  // PRIV1: minors' names on public pages, and a guardian's authorisation of the full name
  "pn1.title": "Nama di halaman awam",
  "pn1.intro": "Undian, keputusan, jadual kedudukan, tangga dan halaman langsung menunjukkan kanak-kanak dengan nama pertama dan huruf pertama nama seterusnya, contohnya “Aina L.”, melainkan anda membenarkan nama penuh di bawah. Pilihan ini milik anda sahaja: venue tidak boleh membuatnya bagi pihak anda, dan menyertai acara tidak bermaksud setuju.",
  "pn1.rules": "Anda boleh membenarkannya untuk satu acara, atau untuk semua penyertaan kanak-kanak ini di satu venue selama {months} bulan. Anda boleh menariknya balik pada bila-bila masa, dan muat semula halaman seterusnya menunjukkan nama pendek semula. Ia juga tamat sendiri apabila acara atau musim tamat, selepas {months} bulan untuk venue, atau jika anda tidak lagi menguruskan kanak-kanak itu. Ia dicatat dalam sejarah {name} dan dalam log aktiviti venue.",
  "pn1.open": "Nama di halaman awam",
  "pn1.none": "{name} tidak mempunyai tempat dalam mana-mana acara, liga atau tangga sekarang, jadi tiada apa yang perlu dibenarkan.",
  "pn1.pick": "Benarkan nama penuh untuk",
  "pn1.choice.tournament": "{name}, kejohanan di {venue} (hingga {date})",
  "pn1.choice.league": "{name}, liga di {venue} (musim ini)",
  "pn1.choice.ladder": "{name}, tangga di {venue} (musim ini)",
  "pn1.choice.venue": "Semua penyertaan {child} di {venue}, selama {months} bulan",
  "pn1.confirm": "Saya ibu bapa atau penjaga {child}. Saya faham bahawa nama penuhnya akan menjadi awam di halaman itu sehingga saya menariknya balik atau ia tamat.",
  "pn1.allow": "Benarkan nama penuh",
  "pn1.inForce": "Dibenarkan sekarang",
  "pn1.inForce.event": "{event} di {venue}: hingga acara atau musim tamat, atau anda menariknya balik",
  "pn1.inForce.venue": "Semua penyertaan di {venue}: hingga {date}, atau anda menariknya balik",
  "pn1.byOther": "diberi oleh penjaga lain",
  "pn1.withdraw": "Tarik balik",
  "pn1.done": "Dibenarkan. Nama penuhnya awam di sana sehingga ia tamat atau anda menariknya balik.",
  "pn1.withdrawn": "Ditarik balik. Nama pendek dipaparkan semula bermula muat semula halaman seterusnya.",
  "pn1.wording.event": "Saya ibu bapa atau penjaga {child}. Saya membenarkan nama penuh {child} dipaparkan di halaman awam {event} di {venue} (undian, keputusan, jadual kedudukan dan halaman langsung) sehingga acara atau musim itu tamat, atau sehingga saya menarik balik kebenaran ini. Saya boleh menariknya balik pada bila-bila masa.",
  "pn1.wording.venue": "Saya ibu bapa atau penjaga {child}. Saya membenarkan nama penuh {child} dipaparkan di halaman awam semua penyertaan pertandingan {child} di {venue} (undian, keputusan, jadual kedudukan, tangga dan halaman langsung) selama {months} bulan, atau sehingga saya menarik balik kebenaran ini. Saya boleh menariknya balik pada bila-bila masa.",
  "pn1.privacyLead": "Nama kanak-kanak di halaman awam.",
  "pn1.privacyBody": "Kanak-kanak yang menyertai kejohanan, liga atau tangga ditunjukkan di halaman awam, halaman langsung dan dalam pemberitahuan kepada keluarga lain dengan nama pertama dan huruf pertama nama seterusnya. Ibu bapa atau penjaganya boleh membenarkan nama penuh untuk satu acara, atau untuk semua penyertaannya di satu venue selama {months} bulan, dan boleh menariknya balik pada bila-bila masa. Ia direkodkan seperti yang diisytiharkan oleh penjaga dan tidak pernah disahkan. {site} belum lagi meminta peguam menyemak perkataan kebenaran ini.",
  "err.PN1_NOT_GUARDIAN": "Anda tidak menguruskan mereka.",
  "err.PN1_NO_ENTRY": "Mereka tidak mempunyai tempat di sana.",
  "err.PN1_NO_SEASON": "Belum ada musim yang dirancang atau sedang berjalan: benarkan apabila ada.",
  "err.PN1_OVER": "Acara itu sudah tamat.",
  "err.PN1_SCOPE": "Pilih satu acara, atau setiap penyertaan di satu venue.",
  "err.PN1_CONFIRM": "Tandakan kotak untuk menyatakan anda faham apa yang menjadi awam.",
  "err.PN1_NOT_FOUND": "Kebenaran itu tidak ditemui.",
  "fi1.consolationNote": "Pemain yang kalah dalam undian utama, kecuali di perlawanan akhir, terus bermain di sini.",
  "err.RT_RANK_AFTER": "Pilih nombor bulat keputusan dikira antara {min} dengan {max}.",
  "err.RT_PROVISIONAL_NEEDS_PUBLIC": "Kedudukan awam mesti dihidupkan sebelum pemain yang belum disenaraikan boleh dipaparkan.",
  "rk1.note": "Penarafan ialah anggaran yang dikira daripada keputusan yang dikira. Dengan sedikit keputusan ia boleh berubah banyak, dan {n} keputusan tidak menjadikannya tepat.",
  "rk1.venueSets": "Setiap pusat memilih bilangan keputusan dikira yang diperlukan seseorang pemain untuk disenaraikan di situ (bilangan lazim ialah {n}).",
  "rk1.provisional.title": "Sementara: kurang daripada {n} keputusan bertarafan; penarafan ini boleh berubah banyak",
  "rk1.provisional.intro":
    "Pemain dan pasukan ini tidak disenaraikan dalam kedudukan. Mereka mempunyai kurang daripada {n} keputusan bertarafan di sini, jadi penarafan mereka hanyalah anggaran kasar. Mereka disenaraikan mengikut nama, bukan mengikut susunan, dan hanya kerana mereka memilih untuk disenaraikan.",
  "rk1.provisional.caption": "Penarafan sementara (tidak disenaraikan dalam kedudukan)",
