  "ofc1.of.afterFinish": "Acara ini telah tamat. Sehingga {date} pautan ini masih menunjukkan keputusan dan membolehkan anda meminta pembetulan, yang diputuskan oleh penganjur. Kiraan tidak lagi boleh dimasukkan di sini.",
  "pmsg.title": "Mesej",
  "pmsg.link": "Mesej",
  "pmsg.intro": "Mesej teks pendek antara orang yang sudah berkongsi permainan, pasukan, kumpulan atau perlawanan.",
  "pmsg.first.title": "Benarkan orang yang bermain dengan saya menghantar mesej",
  "pmsg.first.what": "Anda boleh menulis kepada orang dalam permainan, pasukan, kumpulan atau perlawanan yang anda sertai, dan mereka boleh menulis kepada anda. Tiada siapa boleh mencari anda atau menghantar mesej tiba-tiba: perbualan wujud hanya dalam sesuatu yang sudah anda kongsi, dan ia tamat bersamanya.",
  "pmsg.first.private": "Nombor telefon dan alamat e-mel anda tidak pernah dipaparkan, dan mesej tidak boleh mengandungi nombor telefon atau alamat e-mel. Mesej hanya teks: tiada gambar atau fail.",
  "pmsg.first.safe": "Anda boleh membisukan perbualan, menyekat seseorang dan melaporkan mesej pada bila-bila masa. Sekatan tidak memberitahu mereka apa-apa. Laporan menghantar salinan mesej terakhir kepada kakitangan venue (atau pemilik laman jika tiada venue); tiada orang lain membaca mesej anda.",
  "pmsg.first.adults": "Mesej adalah untuk pemain yang menyatakan mereka berumur 18 tahun ke atas. Kanak-kanak tidak pernah menghantar mesej kepada sesiapa secara peribadi: kanak-kanak hanya boleh menulis dalam perbualan bersama kumpulan belia berselia, dengan persetujuan penjaga dan seorang penyelia yang boleh membacanya. Jika seorang kanak-kanak berada dalam pasukan atau perlawanan, mesej pergi kepada dan datang daripada penjaganya, dipaparkan dengan nama pendek kanak-kanak itu sahaja.",
  "pmsg.first.email": "Kami boleh mengemel anda bahawa anda ada mesej di sesuatu tempat. E-mel itu tidak pernah mengandungi mesej itu sendiri, dan anda menerima paling banyak satu setiap beberapa jam bagi setiap perbualan.",
  "pmsg.first.understood": "Saya telah membaca ini",
  "pmsg.first.turnOn": "Hidupkan mesej",
  "pmsg.first.needAdult": "Anda belum menyatakan anda berumur 18 tahun ke atas, jadi mesej tidak tersedia untuk anda. Anda boleh menyatakannya dalam keutamaan bermain anda.",
  "pmsg.first.preferences": "Keutamaan bermain",
