  "pmy.notice.label": "Bagaimana saya dimaklumkan tentang mesej baharu",
  "pmy.notice.immediate": "Serta-merta, melalui e-mel",
  "pmy.notice.digest": "Ringkasan setiap {n} jam (lalai)",
  "pmy.notice.daily": "Ringkasan sekali sehari",
  "pmy.notice.off": "Tidak sama sekali",
  "pmy.notice.help": "E-mel hanya memberitahu berapa banyak mesej baharu dan di mana, tidak pernah isinya. Laporan dan notis keselamatan sentiasa dihantar serta-merta.",
  "pmy.first.title": "Mesej dalam kumpulan anda",
  "pmy.first.what": "Kumpulan anda ada penyelia. Anda boleh menulis dalam perbualan kumpulan yang dikongsi, dan tidak pernah kepada seorang secara peribadi.",
  "pmy.first.who": "Siapa boleh membacanya: penyelia kumpulan, orang dewasa yang mereka benarkan masuk, orang lain dalam perbualan, dan penjaga anda. Penyelia boleh membaca setiap mesej, dan boleh mengalih keluar mesej, menjeda seseorang atau menutup perbualan. Jika kumpulan meminta venue menjaganya, pengurus venue itu juga boleh membacanya, dan setiap kali dicatat.",
  "pmy.first.rules": "Mesej hanya teks dan pendek. Nombor telefon, e-mel, pautan dan nama media sosial tidak boleh dihantar. Mesej berehat pada waktu malam.",
  "pmy.first.safe": "Anda boleh melaporkan mana-mana mesej dengan butang Lapor. Penjaga anda dimaklumkan jika anda melaporkan sesuatu, dan mana-mana penjaga boleh mematikan mesej untuk anda pada bila-bila masa. Setelah dimatikan, ia kekal mati sehingga penjaga anda yang membuat keputusan bersetuju, atau venue menyelesaikannya.",
  "pmy.first.needGuardian": "Mesej memerlukan penjaga yang menguruskan rekod anda dan dipautkan kepada akaun anda. Minta mereka menghidupkannya untuk anda.",
  "pmy.first.groups": "Kumpulan berselia anda",
  "pmy.first.supervisedBy": "Diselia oleh {names}",
  "pmy.first.guardianOn": "Penjaga anda telah menghidupkannya.",
  "pmy.first.guardianOff": "Dimatikan buat masa ini. Ia memerlukan persetujuan penjaga anda (semua penjaga anda yang membuat keputusan, jika seorang telah mematikannya).",
  "pmy.first.active": "Mesej dihidupkan dalam kumpulan ini.",
  "pmy.first.understood": "Saya sudah membaca ini dan mahu menghidupkan mesej dalam kumpulan ini.",
  "pmy.first.optIn": "Hidupkan mesej dalam kumpulan ini",
  "pmy.first.optOut": "Matikan",
