  "pmy.first.none": "Anda tidak berada dalam kumpulan belia berselia.",
  "pmy.thread.banner.minor": "Kumpulan berselia. Penyelia dan penjaga anda boleh membaca mesej ini.",
  "pmy.thread.banner.adult": "Kumpulan belia berselia: ahli muda berada dalam perbualan ini. Penyelia, pengurus venue (jika kumpulan meminta) dan penjaga ahli muda boleh membaca semuanya. Kekalkan pada sukan.",
  "pmy.thread.supervisors": "Penyelia: {names}",
