  "pmy.group.summary": "Kumpulan belia berselia (lanjutan)",
  "pmy.group.intro": "Tandakan kumpulan ini sebagai kumpulan belia berselia supaya ahli yang belum menyatakan mereka berumur 18 tahun ke atas dapat menyertai perbualan kumpulan, masing-masing hanya dengan persetujuan penjaga dan persetujuan sendiri. Mereka tidak pernah menghantar mesej kepada sesiapa secara peribadi. Anda menjadi penyelia.",
  "pmy.group.mark": "Tandakan sebagai kumpulan belia berselia",
  "pmy.group.marked": "Kumpulan ini ialah kumpulan belia berselia.",
  "pmy.group.ended": "Kumpulan ini bukan lagi kumpulan belia berselia. Perbualannya ditutup.",
  "pmy.group.end": "Berhenti menjadi kumpulan belia (menutup perbualan selama-lamanya)",
  "pmy.group.reason": "Kenapa? (disimpan dalam rekod kumpulan)",
  "pmy.group.adults": "Orang dewasa dalam perbualan",
  "pmy.group.adultsHelp": "Ahli dewasa hanya berada dalam perbualan jika anda membenarkan mereka masuk di sini. Penjaga ahli muda melihat senarai ini, dengan apa yang setiap orang nyatakan tentang diri mereka.",
