  "pmy.group.noAdults": "Belum ada ahli dewasa yang boleh dibenarkan: ahli mesti menyatakan mereka berumur 18 tahun ke atas.",
  "pmy.group.venue": "Venue yang menjaga kumpulan ini (pilihan)",
  "pmy.group.venueHelp": "Jika venue menerima, pengurusnya boleh membaca perbualan untuk perlindungan dan penyederhanaan, setiap bacaan dicatat, dan laporannya dihantar ke venue. Tanpa venue, pemilik platform menguruskan laporan.",
  "pmy.group.venueId": "Nombor venue",
