  "pmy.group.opensWith": "Perbualan dibuka apabila seorang penyelia dan sekurang-kurangnya dua orang boleh membacanya. Seorang penyelia memulakannya.",
  "pmy.group.saved": "Disimpan.",
  "pmy.group.failed": "Itu tidak berjaya.",
  "pmy.guardian.title": "Mesej kumpulan untuk kanak-kanak yang anda wakili",
  "pmy.guardian.intro": "Kanak-kanak yang log masuk sendirinya dipautkan kepada rekodnya hanya boleh menulis dalam perbualan kumpulan belia berselia jika anda menghidupkannya, untuk kanak-kanak itu dan kumpulan itu. Ia sentiasa mati sehingga anda menghidupkannya, anda boleh mematikannya serta-merta, dan tiada yang peribadi: penyelia dan anda boleh membacanya.",
  "pmy.guardian.none": "Tiada kanak-kanak yang anda wakili, yang log masuk sendirinya dipautkan, berada dalam kumpulan belia berselia.",
  "pmy.guardian.supervisors": "Penyelia: {list}",
